import { useEffect, useRef, useState } from 'react';
import { TAB_STATUS } from '../constants/tabStatus.js';
import { deriveTabStatus } from '../utils/tabStatus.js';
import { useEscapeKey } from '../hooks/useEscapeKey.js';
import { unpushedWorkLines } from '../utils/unpushedWork.js';
import DialogShell from './DialogShell.jsx';

/**
 * Hard-confirm dialog for the tab "X" (forget) button.
 *
 * Forgetting a task is destructive and irreversible — it wipes the
 * local clone — so we replace the old native ``window.confirm`` with
 * a designed modal that spells out *exactly* what is lost and forces
 * an explicit click on the danger button. Cancel is the default
 * (auto-focused); Esc and a backdrop click both cancel.
 *
 * The consequence list is context-aware: an in-review task or one
 * with un-pushed changes gets an extra red callout, because that's
 * the case where forgetting actually destroys unrecoverable work.
 *
 * "This task is done" is the one thing in this dialog that reaches
 * OUTSIDE kato: checked, the ticket moves to the tracker's done
 * column (YouTrack / Jira / GitHub / GitLab / Bitbucket) before
 * anything local is wiped. Unchecked — the default — the tracker is
 * left exactly as it is, which is why the effects list flips between
 * two mutually exclusive sentences rather than hedging in one.
 * ``onConfirm`` receives the checkbox state.
 */
export default function ForgetTaskModal({ session, unpushedWork = null, onConfirm, onCancel }) {
  const cancelRef = useRef(null);
  // Default OFF: closing someone's ticket is an outward-facing action,
  // so it only happens when the operator says so on this specific delete.
  const [markDone, setMarkDone] = useState(false);

  useEffect(() => {
    cancelRef.current?.focus();
  }, []);

  useEscapeKey(onCancel);

  if (!session) { return null; }

  const taskId = String(session.task_id || '').trim() || 'this task';
  // The ticket id alone ("UNA-2913") does not tell the operator WHICH piece of
  // work they are about to destroy — a mistaken forget is unrecoverable, so
  // the confirm has to be readable without cross-referencing the tracker.
  const taskTitle = String(session.task_summary || '').trim();
  const baseStatus = deriveTabStatus(session);
  const inReview = baseStatus === TAB_STATUS.REVIEW;
  // ``unpushedWork`` is what UnpushedWorkWarning found just before this
  // dialog opened (the operator chose "Delete anyway"): the callout names
  // the same repositories, so the last screen before the delete says it too.
  const unpushedLines = unpushedWorkLines(unpushedWork).filter((line) => !line.unchecked);
  const hasUnpushed = !!session.has_changes_pending || unpushedLines.length > 0;
  // This task may be a live plan's source: its sub-tasks are forgotten the
  // same way, so the operator sees that before confirming, not after.
  const plan = session.plan_queue;
  const subTaskCount = plan && !['finished', 'cancelled'].includes(plan.status)
    ? (plan.step_count || 0) : 0;

  return (
    <DialogShell
      id="forget-task-modal"
      ariaLabelledBy="forget-task-title"
      title="Forget task?"
      subtitle={taskId}
      subtitleId="forget-task-name"
      onClose={onCancel}
      backdropClose
    >
        {taskTitle && (
          <p className="forget-task-title" id="forget-task-summary">
            {taskTitle}
          </p>
        )}

        <p className="forget-task-lead">
          This permanently deletes kato&rsquo;s local copy of{' '}
          <strong>{taskId}</strong>. It cannot be undone. Here&rsquo;s
          what happens:
        </p>

        <ul className="forget-task-effects">
          <li>
            The per-task workspace clone
            (<code>~/.kato/workspaces/{taskId}/</code> and every
            repository cloned into it) is deleted from disk.
          </li>
          <li>
            Any commits or edits <strong>not already pushed to a pull
            request are lost</strong> — there is no local backup.
          </li>
          <li>
            This tab and its local chat view are removed; the Claude
            session created for this task is dropped.
          </li>
          {markDone ? (
            <li>
              The ticket on the issue tracker is moved to{' '}
              <strong>Done</strong>. If that move fails, nothing is
              deleted and the task stays exactly as it is.
            </li>
          ) : (
            <li>
              The ticket itself on the issue tracker is{' '}
              <strong>not</strong> changed. If it&rsquo;s still in a
              state kato watches, kato may re-clone it fresh on a later
              scan.
            </li>
          )}
          {subTaskCount > 0 && (
            <li>
              This task&rsquo;s plan has{' '}
              <strong>{subTaskCount} sub-task{subTaskCount === 1 ? '' : 's'}</strong>
              {' '}&mdash; they&rsquo;ll be deleted the same way, with
              their own workspace and session.
            </li>
          )}
        </ul>

        <label className="forget-task-done" htmlFor="forget-task-done">
          <input
            id="forget-task-done"
            type="checkbox"
            checked={markDone}
            onChange={(event) => setMarkDone(event.target.checked)}
          />
          <span>
            <strong>This task is done</strong>
            <span className="forget-task-done-hint">
              Also move {taskId} to the Done column on the task tracker.
            </span>
          </span>
        </label>

        {(inReview || hasUnpushed) && (
          <p className="forget-task-warning" role="alert">
            {inReview && (
              <>
                ⚠ This task is <strong>in review (&ldquo;To
                Verify&rdquo;)</strong> — you may still be verifying
                it. Forgetting it now throws away the local clone and
                any fixes that haven&rsquo;t been pushed.{' '}
              </>
            )}
            {hasUnpushed && unpushedLines.length === 0 && (
              <>
                ⚠ This task has <strong>changes ready to push that
                haven&rsquo;t been pushed yet</strong> — they will be
                gone for good.
              </>
            )}
            {unpushedLines.length > 0 && (
              <>
                ⚠ This task has <strong>work that was never pushed</strong>
                {' '}&mdash; it will be gone for good:{' '}
                {unpushedLines
                  .map((line) => `${line.repository} (${line.text})`)
                  .join('; ')}
                .
              </>
            )}
          </p>
        )}

        <div className="modal-actions">
          <button
            id="forget-task-cancel"
            type="button"
            className="secondary"
            ref={cancelRef}
            onClick={onCancel}
          >
            Cancel
          </button>
          <button
            id="forget-task-confirm"
            type="button"
            className="danger"
            onClick={() => onConfirm(markDone)}
          >
            {markDone ? `Finish & forget ${taskId}` : `Forget ${taskId}`}
          </button>
        </div>
    </DialogShell>
  );
}
